/**
 * 模块15：统一请求审计过滤器。
 * 功能：在认证、授权和业务处理外围记录主体、动作、结果、耗时及错误码；不保存敏感请求体。
 * 技术栈：OncePerRequestFilter、ContentCachingResponseWrapper、Jackson与AuditService。
 */
package com.biz.ontology.common.security;
import com.biz.ontology.auth.audit.model.*;import com.biz.ontology.auth.audit.service.AuditService;import com.biz.ontology.common.web.RequestIdContext;import com.fasterxml.jackson.databind.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.util.ContentCachingResponseWrapper;import java.io.IOException;import java.time.LocalDateTime;
@Component public class AuditRequestFilter extends OncePerRequestFilter {private final AuditService audit;private final ObjectMapper mapper;public AuditRequestFilter(AuditService a,ObjectMapper m){audit=a;mapper=m;}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{if(!request.getRequestURI().startsWith("/api/v1/")){chain.doFilter(request,response);return;}long started=System.nanoTime();ContentCachingResponseWrapper wrapped=new ContentCachingResponseWrapper(response);try{chain.doFilter(request,wrapped);}finally{try{AuditLogEntity log=new AuditLogEntity();var authentication=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();String principalType="ANONYMOUS",principalId=null;if(authentication!=null&&authentication.getPrincipal() instanceof PlatformPrincipal p){principalType=p.principalType().name();principalId=p.principalId();}int status=wrapped.getStatus();AuditResult result=status>=400?(status==401||status==403?AuditResult.DENIED:AuditResult.FAILED):AuditResult.SUCCESS;String errorCode=extractCode(wrapped.getContentAsByteArray());log.setRequestId(RequestIdContext.current()==null?"unknown":RequestIdContext.current());log.setPrincipalType(principalType);log.setPrincipalId(principalId);log.setAction(action(request));log.setResult(result);log.setHttpMethod(request.getMethod());log.setPath(request.getRequestURI());log.setDurationMs((System.nanoTime()-started)/1_000_000);log.setClientIp(request.getRemoteAddr());log.setErrorCode(errorCode);log.setCreatedAt(LocalDateTime.now());audit.append(log);}catch(Exception ignored){}finally{wrapped.copyBodyToResponse();}}}private String action(HttpServletRequest r){String path=r.getRequestURI().replaceFirst("^/api/v1/","");return r.getMethod()+":"+(path.length()>100?path.substring(0,100):path);}private String extractCode(byte[] body){try{if(body.length==0)return null;JsonNode node=mapper.readTree(body);JsonNode code=node==null?null:node.get("code");return code==null?null:code.asText();}catch(Exception ignored){return null;}}}
